//! `OpenAPI` component schemas to TypeScript types: the small in-repo generator the register
//! prefers over a new tool. Supports what the contract crates emit (objects, string enums,
//! arrays, refs, nullable types); anything else is an error, never a silent `any`.

use serde_json::Value;

const HEADER: &str =
    "// Generated by `cargo xtask codegen` from the Rust contract crates. Do not edit.\n";

/// All component schemas of `openapi` as TypeScript declarations, in name order.
///
/// # Errors
/// Returns a message naming the schema whose shape the generator does not support.
pub fn render(openapi: &Value) -> Result<String, String> {
    let schemas = openapi
        .pointer("/components/schemas")
        .and_then(Value::as_object)
        .ok_or("document has no components.schemas")?;
    let mut out = String::from(HEADER);
    for (name, schema) in schemas {
        out.push('\n');
        out.push_str(&declaration(name, schema).map_err(|reason| format!("{name}: {reason}"))?);
    }
    Ok(out)
}

fn declaration(name: &str, schema: &Value) -> Result<String, String> {
    let doc = doc_comment(schema, "");
    if let Some(values) = schema.get("enum").and_then(Value::as_array) {
        return Ok(format!("{doc}export type {name} = {};\n", union(values)?));
    }
    match schema.get("type").and_then(Value::as_str) {
        Some("object") => Ok(format!(
            "{doc}export interface {name} {{\n{}}}\n",
            fields(schema)?
        )),
        _ => Err("only objects and string enums are supported at the top level".to_owned()),
    }
}

fn union(values: &[Value]) -> Result<String, String> {
    let members: Result<Vec<String>, String> = values
        .iter()
        .map(|value| {
            value
                .as_str()
                .map(|text| format!("'{text}'"))
                .ok_or("enum value is not a string".to_owned())
        })
        .collect();
    Ok(members?.join(" | "))
}

fn fields(schema: &Value) -> Result<String, String> {
    let required = required_names(schema);
    let properties = schema.get("properties").and_then(Value::as_object);
    let mut out = String::new();
    for (name, property) in properties.into_iter().flatten() {
        out.push_str(&field(name, property, required.contains(&name.as_str()))?);
    }
    Ok(out)
}

fn required_names(schema: &Value) -> Vec<&str> {
    let names = schema.get("required").and_then(Value::as_array);
    names
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .collect()
}

fn field(name: &str, property: &Value, is_required: bool) -> Result<String, String> {
    let marker = ["?", ""]
        .get(usize::from(is_required))
        .copied()
        .unwrap_or("?");
    let doc = doc_comment(property, "  ");
    Ok(format!(
        "{doc}  readonly {name}{marker}: {};\n",
        ts_type(property)?
    ))
}

fn ts_type(schema: &Value) -> Result<String, String> {
    if let Some(reference) = schema.get("$ref").and_then(Value::as_str) {
        return reference
            .rsplit('/')
            .next()
            .map(str::to_owned)
            .ok_or("empty $ref".to_owned());
    }
    match schema.get("type") {
        None => Ok("unknown".to_owned()),
        Some(Value::String(kind)) => scalar_or_array(kind, schema),
        Some(Value::Array(kinds)) => nullable(kinds, schema),
        Some(_) => Err("unsupported type declaration".to_owned()),
    }
}

fn scalar_or_array(kind: &str, schema: &Value) -> Result<String, String> {
    match kind {
        "string" => Ok("string".to_owned()),
        "integer" | "number" => Ok("number".to_owned()),
        "boolean" => Ok("boolean".to_owned()),
        "null" => Ok("null".to_owned()),
        "array" => {
            let items = schema.get("items").ok_or("array without items")?;
            Ok(format!("readonly {}[]", ts_type(items)?))
        }
        other => Err(format!("unsupported type {other}")),
    }
}

fn nullable(kinds: &[Value], schema: &Value) -> Result<String, String> {
    let names: Result<Vec<String>, String> = kinds
        .iter()
        .map(|kind| {
            kind.as_str()
                .ok_or("non-string type".to_owned())
                .and_then(|name| scalar_or_array(name, schema))
        })
        .collect();
    Ok(names?.join(" | "))
}

fn doc_comment(schema: &Value, indent: &str) -> String {
    let text = schema
        .get("description")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if text.is_empty() {
        return String::new();
    }
    format!("{indent}/** {} */\n", text.replace("*/", "*\\/"))
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn objects_enums_refs_and_optional_fields() -> Result<(), String> {
        let document = json!({"components": {"schemas": {
            "Kind": {"type": "string", "enum": ["a", "b"]},
            "Thing": {"type": "object", "description": "A thing.", "required": ["kind", "tags"],
                "properties": {
                    "kind": {"$ref": "#/components/schemas/Kind"},
                    "tags": {"type": "array", "items": {"type": "string"}},
                    "note": {"type": ["string", "null"]},
                    "extra": {}
                }}
        }}});
        let ts = render(&document)?;
        assert!(ts.contains("export type Kind = 'a' | 'b';"), "{ts}");
        assert!(
            ts.contains("/** A thing. */\nexport interface Thing {"),
            "{ts}"
        );
        assert!(ts.contains("  readonly kind: Kind;"), "{ts}");
        assert!(ts.contains("  readonly tags: readonly string[];"), "{ts}");
        assert!(ts.contains("  readonly note?: string | null;"), "{ts}");
        assert!(ts.contains("  readonly extra?: unknown;"), "{ts}");
        Ok(())
    }

    #[test]
    fn unsupported_shapes_fail_loudly() {
        let document = json!({"components": {"schemas": {"Bad": {"oneOf": []}}}});
        assert!(render(&document).is_err_and(|message| message.starts_with("Bad:")));
    }
}
